"""Built-in help; plain text, no GUI or I/O dependencies."""
HELP_SECTIONS = {"zh": [], "en": []}
HELP_SECTIONS['zh'].append(('start', '快速开始与格式', '导入一个或多个文件，检查读数，筛选后导出当前结果。支持 .xlsx、.xls、.csv、.txt、.log、.trc。批量 Excel 仅读首表；单个 Excel 可切换工作表，每次仅读所选表，不是整本工作簿。'))
HELP_SECTIONS['en'].append(('start', 'Start and formats', 'Import files, check counts, filter, then export the current result. Supports .xlsx, .xls, .csv, .txt, .log and .trc. Batch Excel reads the first sheet only. For one Excel file, switch sheets to read the selected sheet, not the whole workbook.'))
HELP_SECTIONS['zh'].append(('import', '替换导入', '成功导入替换旧数据，不是追加；取消或读取失败保留旧数据，不提交部分结果。同一规范化路径只读一次。成功解析但为0行的文件仍在对账中登记；0行不是读取失败。批量按列名对齐，缺列留空。'))
HELP_SECTIONS['en'].append(('import', 'Replacement import', 'A successful import replaces old data; it does not append. Cancellation or a read failure keeps old data without committing partial results. The same normalized path is read once. A successfully parsed 0-row file stays in the report; zero rows do not mean read failure. Batch columns align by name; missing columns are blank.'))
HELP_SECTIONS['zh'].append(('counts', '读数、预览与来源', '解析总数、当前结果数和预览数不是同一口径。预览最多500行，单元格最多显示500字符。来源记录是每文件从1开始的解析记录序号，不是物理行号或 Excel 行号。批量来源列遇同名加后缀；同名文件可能显示完整路径。'))
HELP_SECTIONS['en'].append(('counts', 'Counts, preview and provenance', 'Parsed totals, current result counts and preview counts differ. The preview shows at most 500 rows and 500 characters per cell. Source record is a per-file parsed-record index starting at 1, not a physical line or Excel row number. Batch provenance column names gain suffixes on collisions; duplicate filenames may show full paths.'))
HELP_SECTIONS['zh'].append(('filter', '搜索与条件', '搜索跨所有源列；与条件一起按 AND（全部）或 OR（任一）组合。选列、运算符、输入值及 AND/OR 后，点击应用筛选才生效；从源表重算。搜索、包含、不包含、等于、不等于忽略大小写且非正则；开头/结尾区分大小写。大于/小于按数值比较，非数值不匹配；空/非空检查空白。'))
HELP_SECTIONS['en'].append(('filter', 'Search and conditions', 'Search all source columns. Combine search and conditions with AND (all) or OR (any). Choose column, operator, value and logic, then click Apply filters; results recalculate from source. Search, contains, not contains, equals and not equals ignore case; no regex. Starts/ends with are case-sensitive. Greater/less than compare numbers; nonnumeric values do not match. Empty/not empty test whitespace.'))
HELP_SECTIONS['zh'].append(('extract', '自动提取与恢复', 'values/percent 键名忽略大小写，支持冒号或等号，值到空白、逗号或分号前结束。同一记录两字段均非空才保留。单文件可能默认提取；多文件初次保留全部解析行列。重新自动提取从源表重算，保留来源列；恢复原始数据回到已解析源表，不是重读文件。仅错误筛选需有级别列。'))
HELP_SECTIONS['en'].append(('extract', 'Extraction and restore', 'values/percent keys ignore case, accept colon or equals, and end values at whitespace, comma or semicolon. Both fields must be nonempty in a record. One file may auto-extract; multiple files initially keep all parsed rows/columns. Re-extract recalculates from source and keeps provenance. Restore returns to the parsed source, not a file reread. Error-only filtering needs a level column.'))
HELP_SECTIONS['zh'].append(('table', '去重、列选择与复制', '去重处理当前结果，比较除来源记录外的所有结果列；来源文件参与，隐藏列也参与，跨文件相同行可能保留。列选择影响显示和数据导出，不删除源列。Ctrl/Shift 多选行，Ctrl+C 或右键复制；复制的是预览显示值，受500行及单元格500字符限制，不能代替完整导出。'))
HELP_SECTIONS['en'].append(('table', 'Deduplication, columns and copying', 'Deduplication compares all current-result columns except source record. Source file and hidden columns participate, so equal rows across files may remain. Column selection affects display and data export, not source columns. Use Ctrl/Shift to select rows, Ctrl+C or right-click to copy. Copy uses displayed preview values, limited to 500 rows and 500 characters per cell; it is not a full export.'))
HELP_SECTIONS['zh'].append(('chart', '图表不等于数据导出', '图表使用当前结果，不受表格隐藏列限制；在图表窗口选择系列、横轴和单位。绘图最多抽样5000点，跳过不可绘制值。图表可导出 PNG/PDF/SVG 或含图及绘图数据的 Excel；它不是全量结果文件。完整结果请用主界面的数据导出。'))
HELP_SECTIONS['en'].append(('chart', 'Charts versus data export', 'Charts use the current result, independent of hidden table columns. Choose series, X axis and units in the chart window. Plotting samples at most 5000 points and skips unplottable values. Export PNG/PDF/SVG or Excel with chart and plotted data; this is not the full result file. Use main-window data export for the full result.'))
HELP_SECTIONS['zh'].append(('audit', '逐文件对账与 JSON', '对账含每文件状态、已读/跳过工作表、解析数、保留数、排除数及操作基准。读取总数应等于各文件之和。未应用条件不算已执行。报告是查看时的快照；JSON 需手动保存，不自动随导出生成。不能覆盖已有报告，也不能写到输入或已登记输出路径。报告含路径和筛选值，分享前脱敏；不会自动上传。'))
HELP_SECTIONS['en'].append(('audit', 'Per-file reconciliation and JSON', 'Reports show file status, read/skipped sheets, parsed/kept/excluded counts and operation basis. Read totals must equal file sums. Pending conditions are not applied stages. A report is a snapshot when opened. Save JSON manually; no automatic export sidecar. Existing reports and input/registered-output paths cannot be overwritten. Reports contain paths and filter values: redact before sharing. No automatic upload.'))
HELP_SECTIONS['zh'].append(('fidelity', '导出格式与文本保真', '点击“导出当前结果”先选择格式，再选择保存位置；取消格式选择不导出。数据导出支持 .xlsx、.csv、制表符分隔 .txt，导出当前结果的所选列和所有行，不只预览。缺失值变空，其余规范化为文本。Excel 数字存为文本，公式样式字符串按字面保存；不保留原类型、公式或样式。部分 CSV 导入已推断数字/缺失值，导出不能还原原始字面值。外部软件打开 CSV/TXT 仍可能推断类型或执行公式，请按文本导入。'))
HELP_SECTIONS['en'].append(('fidelity', 'Export formats and text fidelity', 'Click Export Current Result, choose a format, then a save location; cancelling the format choice does not export. Export .xlsx, .csv or tab-separated .txt: selected columns and all current-result rows, not just the preview. Missing values become empty; others normalize to text. Excel numbers are text and formula-like strings are literal; original types, formulas and styles are not preserved. CSV import may already infer numbers/missing values; export cannot restore original literals. External CSV/TXT readers may infer types or execute formulas; import as text.'))
HELP_SECTIONS['zh'].append(('verification', '导出核验与输入保护', '数据导出拒绝覆盖输入文件；先写临时文件，再完整回读核对列名、顺序、所有行和值，通过后才替换目标。写入/核验失败不覆盖已有目标；成功导出可能替换旧输出。Excel 超行列数、单元格长度或非法字符会失败。核验仅证明导出当时与当前规范化结果一致，不证明源解析语义正确，也不保证文件以后未改变。'))
HELP_SECTIONS['en'].append(('verification', 'Verification and input protection', 'Data export refuses input paths. It writes a temporary file and reads back column names/order, all rows and values before replacing the destination. Write/verification failure leaves an existing destination intact; success may replace old output. Excel dimension, cell-length or illegal-character limits can fail export. Verification concerns the normalized result at export time, not source parsing correctness or later file changes.'))
HELP_SECTIONS['zh'].append(('faq', '常见问题、语言与软件信息', '0结果先检查已应用条件和双字段要求，再恢复源表排查。大文件先用小样本验证；解析、合并、对账、全量回读有随数据量线性增长的内存成本，可能耗时或内存不足，不保证百万行流畅。批量仅读首表。左下角“关于”菜单含使用指南、语言与软件信息。清空数据不删除原文件。'))
HELP_SECTIONS['en'].append(('faq', 'Troubleshooting, language and software information', 'Zero results: check applied filters and both required fields, then restore source. Test large files on a small sample first. Parsing, merging, reconciliation and full read-back have linear memory costs; delays or memory exhaustion are possible, with no million-row performance guarantee. Batch reads first sheets only. Bottom-left About includes User guide, Language and Software information. Clear data does not delete source files.'))

def help_text(lang):
    """Render supported languages; reject unknown language codes."""
    if lang not in ('zh', 'en'):
        raise ValueError('Unsupported language')
    return '\n\n'.join(t + '\n' + b for _, t, b in HELP_SECTIONS[lang])
